{"alloy":{"configMap":{"content":"
otelcol.receiver.otlp "gateway" {
  http {
    endpoint = "0.0.0.0:4318"
    max_request_body_size = "64MiB"
  }

  output {
    traces = [
      otelcol.processor.batch.tempo.input,
      otelcol.processor.tail_sampling.llm.input,
    ]
  }
}

otelcol.processor.batch "tempo" {
  output {
    traces = [otelcol.exporter.otlphttp.tempo.input]
  }
}

otelcol.exporter.otlphttp "tempo" {
  client {
    endpoint = "http://tempo.tempo.svc.cluster.local:4318"
  }
}

otelcol.processor.tail_sampling "llm" {
  decision_wait = "120s"

  decision_cache = {
    sampled_cache_size = 100000,
  }

  policy {
    name = "llm-traces"
    type = "ottl_condition"

    ottl_condition {
      error_mode = "ignore"
      span = [
        "attributes[\"gen_ai.system\"] != nil",
        "attributes[\"gen_ai.request.model\"] != nil",
        "attributes[\"gen_ai.operation.name\"] != nil",
      ]
    }
  }

  output {
    traces = [
      otelcol.processor.filter.px_scout_beta.input,
      otelcol.processor.filter.px_scout_prod.input,
      otelcol.processor.filter.px_birmel.input,
      otelcol.processor.filter.px_temporal.input,
      otelcol.processor.filter.px_discord_plays.input,
      otelcol.processor.filter.px_misc.input,
    ]
  }
}

otelcol.auth.bearer "phoenix" {
  token = sys.env("PHOENIX_API_KEY")
}

otelcol.processor.filter "px_scout_beta" {
  error_mode = "ignore"

  traces {
    span = [
      "not(resource.attributes[\"service.name\"] == \"scout-backend\" and resource.attributes[\"deployment.environment.name\"] == \"beta\")",
    ]
  }

  output {
    traces = [otelcol.exporter.otlphttp.px_scout_beta.input]
  }
}

otelcol.exporter.otlphttp "px_scout_beta" {
  client {
    endpoint = "http://phoenix.phoenix.svc.cluster.local:6006"
    auth     = otelcol.auth.bearer.phoenix.handler
    headers  = {
      "x-project-name" = "scout-beta",
    }
  }
}

otelcol.processor.filter "px_scout_prod" {
  error_mode = "ignore"

  traces {
    span = [
      "not(resource.attributes[\"service.name\"] == \"scout-backend\" and resource.attributes[\"deployment.environment.name\"] == \"prod\")",
    ]
  }

  output {
    traces = [otelcol.exporter.otlphttp.px_scout_prod.input]
  }
}

otelcol.exporter.otlphttp "px_scout_prod" {
  client {
    endpoint = "http://phoenix.phoenix.svc.cluster.local:6006"
    auth     = otelcol.auth.bearer.phoenix.handler
    headers  = {
      "x-project-name" = "scout-prod",
    }
  }
}

otelcol.processor.filter "px_birmel" {
  error_mode = "ignore"

  traces {
    span = [
      "resource.attributes[\"service.name\"] != \"birmel\"",
    ]
  }

  output {
    traces = [otelcol.exporter.otlphttp.px_birmel.input]
  }
}

otelcol.exporter.otlphttp "px_birmel" {
  client {
    endpoint = "http://phoenix.phoenix.svc.cluster.local:6006"
    auth     = otelcol.auth.bearer.phoenix.handler
    headers  = {
      "x-project-name" = "birmel",
    }
  }
}

otelcol.processor.filter "px_temporal" {
  error_mode = "ignore"

  traces {
    span = [
      "resource.attributes[\"service.name\"] == nil",
      "not(IsMatch(resource.attributes[\"service.name\"], \"^temporal-\"))",
    ]
  }

  output {
    traces = [otelcol.exporter.otlphttp.px_temporal.input]
  }
}

otelcol.exporter.otlphttp "px_temporal" {
  client {
    endpoint = "http://phoenix.phoenix.svc.cluster.local:6006"
    auth     = otelcol.auth.bearer.phoenix.handler
    headers  = {
      "x-project-name" = "temporal",
    }
  }
}

otelcol.processor.filter "px_discord_plays" {
  error_mode = "ignore"

  traces {
    span = [
      "not(resource.attributes[\"service.name\"] == \"discord-plays-pokemon\" or resource.attributes[\"service.name\"] == \"discord-plays-mario-kart\")",
    ]
  }

  output {
    traces = [otelcol.exporter.otlphttp.px_discord_plays.input]
  }
}

otelcol.exporter.otlphttp "px_discord_plays" {
  client {
    endpoint = "http://phoenix.phoenix.svc.cluster.local:6006"
    auth     = otelcol.auth.bearer.phoenix.handler
    headers  = {
      "x-project-name" = "discord-plays",
    }
  }
}

otelcol.processor.filter "px_misc" {
  error_mode = "ignore"

  traces {
    span = [
      "not(resource.attributes[\"service.name\"] == \"streambot\" or resource.attributes[\"service.name\"] == \"alert-dashboard\")",
    ]
  }

  output {
    traces = [otelcol.exporter.otlphttp.px_misc.input]
  }
}

otelcol.exporter.otlphttp "px_misc" {
  client {
    endpoint = "http://phoenix.phoenix.svc.cluster.local:6006"
    auth     = otelcol.auth.bearer.phoenix.handler
    headers  = {
      "x-project-name" = "misc",
    }
  }
}

otelcol.receiver.otlp "tailnet_metrics" {
  http {
    endpoint = "0.0.0.0:4319"
  }

  output {
    metrics = [otelcol.processor.filter.tailnet_metrics.input]
  }
}

otelcol.processor.filter "tailnet_metrics" {
  metrics {
    metric = [
      "not IsMatch(name, \"^(ai_usage_|ai_subscription_)\")",
    ]
  }

  output {
    metrics = [otelcol.processor.batch.tailnet_metrics.input]
  }
}

otelcol.processor.batch "tailnet_metrics" {
  output {
    metrics = [otelcol.exporter.prometheus.tailnet.input]
  }
}

otelcol.exporter.prometheus "tailnet" {
  add_metric_suffixes  = false
  include_target_info  = false
  include_scope_labels = false
  forward_to           = [prometheus.remote_write.cluster.receiver]
}

prometheus.remote_write "cluster" {
  endpoint {
    url = "http://prometheus-kube-prometheus-prometheus.prometheus:9090/api/v1/write"
    authorization {
      type        = "Bearer"
      credentials = sys.env("PROMETHEUS_WRITE_TOKEN")
    }
  }
}
"},"extraEnv":[{"name":"PHOENIX_API_KEY","valueFrom":{"secretKeyRef":{"key":"PHOENIX_API_KEY","name":"phoenix-ingest"}}},{"name":"PROMETHEUS_WRITE_TOKEN","valueFrom":{"secretKeyRef":{"key":"prometheus-write-token","name":"alloy-gateway-monitoring-api-auth"}}}],"extraPorts":[{"name":"otlp-http","port":4318,"protocol":"TCP","targetPort":4318},{"name":"otlp-metrics","port":4319,"protocol":"TCP","targetPort":4319}],"resources":{"requests":{"cpu":"100m","memory":"256Mi"}}},"controller":{"replicas":1,"type":"deployment"},"crds":{"create":false},"fullnameOverride":"alloy-gateway","rbac":{"create":false},"serviceAccount":{"automountServiceAccountToken":false},"serviceMonitor":{"additionalLabels":{"release":"prometheus"},"enabled":true}}
